using CourseManagementSystem.Data; using CourseManagementSystem.DTOs.Categories; using CourseManagementSystem.Models; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore;
namespace CourseManagementSystem.Controllers;
[ApiController][Route("api/[controller]")] public class CategoriesController(ApplicationDbContext context) : ControllerBase {
[HttpGet] public async Task<ActionResult<IEnumerable<CategoryResponseDto>>> GetAll()=>Ok(await context.Categories.AsNoTracking().OrderBy(x=>x.Name).Select(x=>new CategoryResponseDto(x.Id,x.Name,x.Description)).ToListAsync());
[HttpGet("{id:int}")] public async Task<ActionResult<CategoryResponseDto>> GetById(int id){var x=await context.Categories.AsNoTracking().Where(x=>x.Id==id).Select(x=>new CategoryResponseDto(x.Id,x.Name,x.Description)).FirstOrDefaultAsync(); return x is null?NotFound():Ok(x);}
[HttpPost] public async Task<ActionResult<CategoryResponseDto>> Create(CategoryCreateDto dto){if(await context.Categories.AnyAsync(x=>x.Name==dto.Name)) return Conflict(new{message="Category name already exists."}); var x=new Category{Name=dto.Name.Trim(),Description=dto.Description}; context.Categories.Add(x); await context.SaveChangesAsync(); var r=new CategoryResponseDto(x.Id,x.Name,x.Description); return CreatedAtAction(nameof(GetById),new{id=x.Id},r);}
[HttpPut("{id:int}")] public async Task<IActionResult> Update(int id,CategoryUpdateDto dto){var x=await context.Categories.FindAsync(id); if(x is null)return NotFound(); if(await context.Categories.AnyAsync(c=>c.Id!=id&&c.Name==dto.Name))return Conflict(new{message="Category name already exists."}); x.Name=dto.Name.Trim();x.Description=dto.Description;await context.SaveChangesAsync();return NoContent();}
[HttpDelete("{id:int}")] public async Task<IActionResult> Delete(int id){var x=await context.Categories.FindAsync(id);if(x is null)return NotFound();if(await context.Courses.AnyAsync(c=>c.CategoryId==id))return Conflict(new{message="Cannot delete a category that has courses."});context.Categories.Remove(x);await context.SaveChangesAsync();return NoContent();}
}
